  constructor(
    public controller: DatoPersonalService,
    private utils: UtilsService,
    private route: ActivatedRoute,
    private router: Router,
    private storage: LocalStorageService
  ) { }

  ngOnInit() {
    const login = this.storage.getClienteUser()
    console.log("cliente_id:", login?.id)

      const id = login?.datos_personales_id
      if (this.edit && this.edit.id == id) {
        return
      }
      if (id) {
        this.getFormData(id)
      }
  }

  public async getFormData(id: number){
    this.edit = await this.controller.find(id, [
      'telefonosPersonales',
      'ciudades'
    ])
    console.log(this.edit)
  }
